        Expression::StringLiteral(s) => format!("\"{}\"", js_text::lossy(s.value)),
        Expression::BooleanLiteral(b) => b.value.to_string(),
        Expression::NullLiteral(_) => "null".to_owned(),
        _ => "unknown".to_owned(),

