  name: string
  propType: PropType
  required: boolean
  description: string
}

export type PropType =
  | { kind: 'string' }
  | { kind: 'number' }
  | { kind: 'boolean' }
  | { kind: 'null' }
  | { kind: 'undefined' }
  | { kind: 'any' }
  | { kind: 'never' }
  | { kind: 'unknown' }
  | { kind: 'void' }
  | { kind: 'reactNode' }
  | { kind: 'cssProperties' }
  | { kind: 'elementType' }
  | { kind: 'sxProps' }
  | { kind: 'stringLiteral'; value: string }
  | { kind: 'numberLiteral'; value: number }
  | { kind: 'boolLiteral'; value: boolean }
  | { kind: 'union'; members: PropType[] }
  | { kind: 'intersection'; members: PropType[] }
  | { kind: 'array'; element: PropType }
  | { kind: 'tuple'; elements: PropType[] }
  | { kind: 'object'; fields: ObjectField[] }
  | { kind: 'named'; name: string; args: PropType[] }
  | { kind: 'function'; typeParams: string[]; params: FunctionParam[]; returnType: PropType }
  | { kind: 'ref'; element: string | null }
  | { kind: 'htmlAttributes'; element: string; omitted: string[] }
  | { kind: 'literalUnion'; members: string[]; hasDefault: boolean }
  | { kind: 'opaque'; raw: string; reason: OpaqueReason }

export interface ParsedProp {
  name: string
  type: PropType
  required: boolean
  defaultValue: DefaultValue | null
  description: string
  tags: Record<string, string>
  parent: PropParent | null
  declarations: PropParent[]
}

/**
 * A prop's key in a `props` table: 16 hex digits hashed from the prop's JSON, so the same prop has the same id in every
 * output and update of a build. Opaque: never store one beyond the output it came from.
 */
export type PropId = string

/**
 * A prop set's key in a `propSets` table: the props one declaring type contributes to a component, as prop name to
 * `PropId`. Components that inherit the type share the set. Opaque like `PropId`.
 */
export type PropSetId = string

/** A list's key in a `nameLists` table: the prop names an `Omit` removed at one inheritance layer. Opaque like `PropId`. */
export type NameListId = string

/** Prop name to the prop's id in the output's (or update's) `props` table. */
export type PropSet = Record<string, PropId>

export interface ComponentEntry {
  displayName: string
  filePath: string
  description: string
  /**
